export type InspectorCategory = {
  slug:string; title:string; cluster:string; answer:string; note:string;
  criteria:{title:string;body:string}[]; faqs:{q:string;a:string}[];
  workflowSlugs:string[]; products:ElectricianCandidate[];
  sections:{heading:string;body:string}[];
};
function group(slug:string,title:string,cluster:string,answer:string,note:string,criteria:[string,string][],faqs:[string,string][],jobs:string[],products:ElectricianCandidate[]):InspectorCategory {
  return {slug,title,cluster,answer,note,criteria:criteria.map(([title,body])=>({title,body})),faqs:faqs.map(([q,a])=>({q,a})),workflowSlugs:jobs,products,
    sections:criteria.map(([heading,body])=>({heading,body}))};
}
function reuse(categories:{slug:string;products:ElectricianCandidate[]}[],slug:string,context:Record<string,[string,string,string]>):ElectricianCandidate[] {
  const source=categories.find(c=>c.slug===slug);
  if(!source)throw new Error(`Missing documented category: ${slug}`);
  return source.products.map(p=>{
    const [fit,limit,reason]=context[p.id];
    return {...p,assessment:{...p.assessment,bestFor:fit,avoidIf:limit,intro:reason,
      verdict:`${reason} ${limit} Choose the complete package for your inspection and reporting routine.`,
      cons:[limit,...p.assessment.cons],analysis:[reason,limit,'Record the location and conditions alongside readings. Follow the tool instructions and the agreed inspection scope.']}};
  });
}
