inspectorCategories.push(
  group('best-combustible-gas-detectors-for-home-inspectors','Best Combustible Gas Detectors for Home Inspectors: Defined Scope and Indications','Gas & CO Instruments',
    'Compare ET120, CD100A, CD200 and micro CD-100 for their documented combustible-gas roles. DRX3 is a broader application-specific comparison for qualified users.',
    'These are purchasing comparisons, not instructions to investigate an active gas emergency. A detector is not a personal safety alarm or a building gas-safety certificate.',
    [['Identify the gas and intended role','Combustible-gas, refrigerant and carbon-monoxide detection are different applications. Confirm the exact supported gas and operating environment for the instrument.'],['Understand indications and maintenance','Sensor condition, clean-air setup and prescribed checks influence indications. A tick rate is not a universal laboratory concentration measurement.'],['Prepare the reporting and response scope','Record an appropriate observation without certifying an entire gas installation. Suspected hazardous conditions require the applicable emergency response rather than continued investigation.']],
    [['Is a refrigerant detector automatically a gas detector?','No. Confirm the exact supported gases and permitted application.'],['Does no indication prove there are no leaks?','No. Access, operating conditions and instrument limitations affect what can be observed.']],[j.systems,j.purchase],gas),
  group('best-carbon-monoxide-meters-for-home-inspectors','Best Carbon Monoxide Meters for Home Inspectors: Ambient Readings and Recording','Gas & CO Instruments',
    'Compare ET110, SCM4, CO71A, CO-220 and 317-3 by local display, maximum capture, sensor maintenance and the documented ambient measurement role.',
    'Ambient CO instruments do not replace required installed alarms, personal protective equipment or a qualified combustion assessment.',
    [['Choose ambient measurement deliberately','An ambient meter observes the air at a location and time. A combustion analyzer samples and assesses a different application; do not substitute one for the other.'],['Plan maintenance before purchase','Check sensor life, service availability, calibration and pre-use checks. A numerical display is only useful when the instrument is maintained and used correctly.'],['Keep the record bounded','Record time, place, operating state and the instrument used. A spot reading does not certify future conditions or the safety of every appliance. Follow the appropriate response to a suspected hazardous condition.']],
    [['Can this replace a household CO alarm?','No. A portable measurement instrument and a required installed alarm have different roles.'],['Does a zero spot reading certify a furnace?','No. It is a limited ambient observation, not a complete appliance or combustion assessment.']],[j.systems,j.purchase,j.listing],co),
  group('best-laser-measures-for-home-inspectors','Best Laser Measures for Home Inspectors: Dimensions That Reach the Report','Measuring & Access',
    'Compare connected GLM165-27CG and D2-v1 with simpler GLM100-23, calculation-oriented GLM165-40 and compact Klein 93LDM100C.',
    'Published range and accuracy describe documented conditions, not our field tests. Match the generation and current manufacturer notices.',
    [['Measure from a known reference','Select the correct front, rear or endpiece reference and a suitable target. Keep the relevant dimension and location together rather than transcribing an unexplained number.'],['Decide how dimensions enter the report','Connected transfer can reduce manual transcription, but check phone compatibility and the actual export routine. A simpler local display may fit a smaller scope.'],['Distinguish dimensions from surveys','Distance and area functions do not establish a legal boundary, code compliance or a full measured survey. Use the measurements within the agreed inspection scope.']],
    [['Is maximum range the main buying decision?','Usually the needed indoor dimensions, readability and recording workflow matter more. Target and environmental conditions still affect measurement.'],['Is D2-v1 the latest D2?','No. It is the specified older Bluetooth configuration; newer generations have their own features.']],[j.purchase,j.listing,j.starter],lasers),
  group('best-ladders-for-home-inspectors','Best Ladders for Home Inspectors: Access, Load and Transport','Measuring & Access',
    'Compare Werner 6006S for a fixed short stepladder, Velocity Model 17 for its articulated arrangement, and Gorilla GLMPXA-18-2 for another multi-position configuration.',
    'There is no universal ladder for every property. Choose a suitable permitted access arrangement and report areas that cannot be safely inspected.',
    [['Separate length, reach and standing height','Marketing reach is not a permitted standing point. Use the exact model’s configuration, instructions and labels to decide whether the access is suitable.'],['Count the complete load','The user, clothing, tools and any carried equipment contribute to the rated load. A bag recommendation does not remove that limit.'],['Fit the property and vehicle','Check setup space, support, access geometry, transport dimensions and handling. Fiberglass rails do not permit unsafe electrical proximity, and aluminum conducts electricity.']],
    [['Does an articulated ladder mean I must access the roof?','No. The inspection scope and actual safe access determine the observation method. Report limitations when access is unsuitable.'],['Why only three choices?','They cover distinct documented access arrangements without padding the shortlist with similar sizes.']],[j.attic,j.purchase,j.listing],ladders),
);
